      location: "Nairobi, Kenya",
      focus: "Data Science, Machine Learning, Business Automation, & Agribusiness",
      languages: ["English (Professional)", "Arabic (Professional)"]
    },

    summary: "An AI Engineer and Machine Learning Specialist with over nine years of professional experience spanning enterprise automation, data analytics, and geostrategic economic research. Expert at taking complex data structures and turning them into production-grade automated solutions. Currently bridging the gap between advanced data science and on-the-ground business transformation, with active ventures in AI consultancy and precision agribusiness in East Africa.",

    skills: {
      ai_automation: [
        "Production workflow automation & live data integration pipelines (n8n)",
        "Multi-agent AI orchestration & autonomous agent-to-agent task delegation",
        "Generative AI ecosystems — Vertex AI, multimodal embeddings, long-context reasoning",
        "Lead generation frameworks, intelligent customer routing, automated ROI engines"
      ],
      data_science_ml: [
        "Predictive modeling, statistical forecasting, multi-variable regression",
        "Unsupervised learning — K-Means clustering, anomaly detection, customer segmentation",
        "Data parsing, dataset validation, EDA",
        "Matrix operations, linear algebra, symbolic mathematics (NumPy, SymPy), probability distributions"
      ],
      tech_stack: [
        "Python (NumPy, SymPy)",
        "SQL — relational database design & complex query optimization",
        "Google Cloud Platform (GCP) — scalable data pipelines & data warehouse",
        "GitHub — version control, modular architecture, CI/CD"
      ],
      domain: [
        "Geostrategy & trade logistics — East Africa & Sahel regional trade corridors",
        "Maritime infrastructure development & cross-border supply chain logistics",
        "Agricultural biotechnology — agronomic trends, crop ecology, high-yielding seed distribution"
      ]
    },

    experience: [
      {
        title: "Founder & Principal Consultant",
        company: "YSL Solutions",
        type: "AI Business Automation Consultancy",
        start: "2026-01",
        end: null,
        current: true,
        highlights: [
          "Operate a global AI business automation consultancy specializing in intelligent workflow design for digital transformation",
          "Deploy production-grade automated engines that reduce operational overhead and scale lead generation for international clients"
        ]
      },
      {
        title: "Agribusiness Entrepreneur",
        company: "Seed Distribution Venture",
        type: "Agribusiness",
        location: "Nairobi, Kenya",
        start: "2026",
        end: null,
        current: true,
        highlights: [
          "Formulating data-driven market strategies for high-yielding seed distribution in Kenya",
          "Applying agricultural biotechnology expertise to optimize supply chains and increase farmer access to high-performance inputs"
        ]
      },
      {
        title: "Economic Researcher",
        company: "United Nations Economic Commission for Africa",
        type: "Research",
        start: null,
        end: null,
        current: false,
        highlights: [
          "Conducted macro-analytical research on regional trade corridors, maritime infrastructure, and cross-border logistics",
          "Synthesized geostatistical datasets into actionable economic policy insights for East Africa"
        ]
      }
    ],

    education: [
      {
        degree: "Master of Data Science (Candidate)",
        institution: "University of Pittsburgh",
        focus: ["Large Language Models (LLMs)", "Data Visualization"],
        achievement: "98% performance metric in core data-centric computing sequences",
        status: "In Progress"
      },
      {
        degree: "B.S. in Agricultural Biotechnology & Agroecology",
        institution: "Virginia Tech",
        status: "Completed"
      }
    ],

    certifications: [
      {
        name: "Google Cloud Professional Data Engineer",
        issuer: "Google",
        short: "GCP"
      },
      {
        name: "IABAC Certified Data Scientist & AI Expert",
        issuer: "IABAC",
        short: "IABAC DS/AI"
      }
    ],

    tools: [
      "Google Colab",
      "Jupyter Notebooks",
      "GitHub",
      "n8n",
      "Vertex AI",
      "Google Cloud Platform"
    ]
  }
}];

const p = $input.first().json;

// --- LinkedIn About Section (2,600 char limit) ---
const certLine = p.certifications.map(c => c.name).join(' | ');
const techLine = p.skills.tech_stack.join(' · ');

const about = `${p.summary}

🛠️ What I Build
${ p.skills.ai_automation.map(s => '▸ ' + s).join('\n') }

📊 Data Science & ML
${ p.skills.data_science_ml.map(s => '▸ ' + s).join('\n') }

💻 Tech Stack
${ techLine }

🎓 Credentials
${ p.education.map(e => `${e.degree} — ${e.institution}`).join('\n') }
${ certLine }

🌍 Based in ${p.personal.location} | Open to global collaborations`;

return [{
  json: {
    output_type: 'linkedin_about',
    character_count: about.length,
    within_limit: about.length <= 2600,
    text: about
  }
}];

const p = $input.first().json;

// --- Structured Resume JSON (API / ATS ready) ---
const resume = {
  meta: {
    format: "resume_v1",
    generated_at: new Date().toISOString(),
    name: p.personal.name
  },
  contact: {
    name: p.personal.name,
    location: p.personal.location,
    languages: p.personal.languages
  },
  summary: p.summary,
  experience: p.experience.map(e => ({
    title: e.title,
    company: e.company,
    period: e.current ? `${e.start} – Present` : `${e.start || 'N/A'} – ${e.end || 'N/A'}`,
    location: e.location || null,
    bullets: e.highlights
  })),
  education: p.education.map(e => ({
    degree: e.degree,
    institution: e.institution,
    status: e.status,
    notes: e.focus ? `Focus: ${e.focus.join(', ')}` : (e.achievement || null)
  })),
  certifications: p.certifications.map(c => `${c.name} (${c.issuer})`),
  skills: {
    ai_automation: p.skills.ai_automation,
    data_science_ml: p.skills.data_science_ml,
    tech_stack: p.skills.tech_stack,
    domain_expertise: p.skills.domain
  },
  tools: p.tools
};

return [{
  json: {
    output_type: 'structured_resume',
    resume
  }
}];
